 /// <summary>
 /// Moves an invoice through its lifecycle: Draft -> PendingApproval -> Approved or Rejected.
 /// One invoice at a time, decided as a whole by a single approver.
 /// In this demo, each request has its own service instance and shares one
 /// in-memory repository. GetById returns the same mutable Invoice object for
 /// a given ID; repository GetById and Update each lock their own list access.
 /// These decision methods operate on submitted invoices. Concurrent decision
 /// calls may target the same invoice. Concurrent submission/deletion, external
 /// writers and repositories returning detached copies are outside this fixture.
 /// </summary>
 public class ApprovalService
 {
     private readonly IInvoiceRepository _repository;

     public ApprovalService(IInvoiceRepository repository)
     {
         _repository = repository;
     }

     public Invoice Submit(string invoiceId)
     {
         var invoice = Find(invoiceId);

         if (invoice.Status != InvoiceStatus.Draft)
         {
             throw new InvalidOperationException(
                 $"Invoice {invoiceId} is {invoice.Status}; only drafts can be submitted.");
         }

         invoice.Status = InvoiceStatus.PendingApproval;
         _repository.Update(invoice);
         return invoice;
     }

+    public Invoice Approve(string invoiceId, string approver)
+    {
+        var invoice = Find(invoiceId);
+        EnsurePending(invoice);
+
+        invoice.Status = InvoiceStatus.Approved;
+        invoice.DecidedBy = approver;
+        invoice.DecidedAt = DateTime.UtcNow;
+        _repository.Update(invoice);
+        return invoice;
+    }
+
+    public Invoice Reject(string invoiceId, string approver, string reason)
+    {
+        if (string.IsNullOrWhiteSpace(reason))
+        {
+            throw new ArgumentException("A reason is required to reject an invoice.", nameof(reason));
+        }
+
+        var invoice = Find(invoiceId);
+        EnsurePending(invoice);
+
+        invoice.Status = InvoiceStatus.Rejected;
+        invoice.DecidedBy = approver;
+        invoice.DecidedAt = DateTime.UtcNow;
+        invoice.DecisionNote = reason;
+        _repository.Update(invoice);
+        return invoice;
+    }
+
     private Invoice Find(string invoiceId) =>
         _repository.GetById(invoiceId)
         ?? throw new KeyNotFoundException($"Invoice {invoiceId} was not found.");

     private static void EnsurePending(Invoice invoice)
     {
         if (invoice.Status != InvoiceStatus.PendingApproval)
         {
             throw new InvalidOperationException(
                 $"Invoice {invoice.Id} is {invoice.Status}; only pending invoices can be decided.");
